INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 18, 'theory', 'Quiz: collections and errors');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 18, 0, 'What does a Vec<i32> keep on the stack?', '["All the elements in a row", "Only a pointer", "A table of hash values", "A pointer to the buffer, the length and the capacity: three words"]', 3, 'The elements themselves lie on the heap, in a row and without headers. When the capacity runs out, push allocates a buffer twice as large and moves the elements there, so appending costs a constant amortized.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 18, 1, 'What does *map.entry(word).or_insert(0) += 1 do?', '["Creates a new entry on every call, overwriting the old one", "Finds the slot by key, puts 0 there if it is missing, and increments the counter through &mut", "Panics if the word is missing", "Copies the whole table"]', 1, 'entry is a single hash lookup; or_insert returns a mutable reference to the value, so the counter is incremented in place.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 18, 2, 'What does the ? operator do in a function returning Result<T, E> if the expression returned Err?', '["Panics", "Ignores the error and continues", "Immediately returns Err from the function, converting the error through From", "Prints a message and terminates the process"]', 2, '? unwraps Ok into the value, and on Err returns the error outward; if the error types differ, From::from is called.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 18, 3, 'What happens to the values lying in the frames on a panic (panic = unwind)?', '["The stack is unwound and drop is called for the values", "Nothing: the memory is simply abandoned", "They are copied to the heap", "The program stops at once, as after abort"]', 0, 'Rust walks up the frames and calls drop: files are closed, locks are released. The process ends with exit code 101 unless the panic is caught.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 18, 4, 'How does collect::<Result<Vec<i32>, _>>() behave over an iterator of string-parsing results?', '["Returns Ok with all the successful numbers, skipping the errors", "Stops at the first error and returns it", "Panics on any error", "Returns a vector and discards the errors"]', 1, 'If all the elements are Ok, you get Ok(Vec). At the first error, collecting stops and that Err is returned. To discard the failed ones, use filter_map(Result::ok).');
